            repeatList.add(rleStart / 3);
        }
        rleCount *= 7;
        rleStart *= -3;
    }
    int bitWidth = ReadWriteForEncodingUtils.getLongMaxBitWidth(repeatList);
    for (int i = 1; i < 10; i++) {
        testLength(repeatList, false, i);
    }
}

